    public static uint InterfaceVersion => 4;

    private WlOutput(nint handle) : base(handle) { }

    public static WlOutput Wrap(nint handle) => new(handle);

    /// <summary>subpixel geometry information</summary>
    public enum Subpixel : uint
    {
        Unknown = 0,
        None = 1,
        HorizontalRgb = 2,
        HorizontalBgr = 3,
        VerticalRgb = 4,
        VerticalBgr = 5,
    }

    /// <summary>transform from framebuffer to output</summary>
    public enum Transform : uint
    {
        Normal = 0,
        _90 = 1,
        _180 = 2,
        _270 = 3,
        Flipped = 4,
        Flipped90 = 5,
        Flipped180 = 6,
        Flipped270 = 7,
    }

    /// <summary>mode information</summary>
    [System.Flags]
    public enum ModeKind : uint
    {
        Current = 0x1,
        Preferred = 0x2,
    }

    /// <summary>release the output object</summary>
    /// <remarks>Since version 3.</remarks>
    public void Release()
    {
        Emit(0, null);
        DestroyProxy();
    }

    /// <summary>properties of the output</summary>
    public event System.Action<int, int, int, int, int, string, string, int>? Geometry;

    /// <summary>advertise available modes for the output</summary>
    public event System.Action<uint, int, int, int>? Mode;

    /// <summary>sent all information about output</summary>
    public event System.Action? Done;

    /// <summary>output scaling properties</summary>
    public event System.Action<int>? Scale;

    /// <summary>name of this output</summary>
    public event System.Action<string>? Name;

    /// <summary>human-readable description of this output</summary>
    public event System.Action<string>? Description;

    protected override void Dispatch(uint opcode, WlArgument* a)
    {
        switch (opcode)
        {
            case 0:
                Geometry?.Invoke(a[0].I, a[1].I, a[2].I, a[3].I, a[4].I, Text(a[5].P)!, Text(a[6].P)!, a[7].I);
                break;
            case 1:
                Mode?.Invoke(a[0].U, a[1].I, a[2].I, a[3].I);
                break;
            case 2:
                Done?.Invoke();
                break;
            case 3:
                Scale?.Invoke(a[0].I);
                break;
            case 4:
                Name?.Invoke(Text(a[0].P)!);
                break;
            case 5:
                Description?.Invoke(Text(a[0].P)!);
                break;
        }
    }
}

